function countFilters(){const difficulties=new Set($$('[name=difficulty]:checked').map(b=>b.value)),selected=new Set($$('[data-topic]:checked').map(b=>b.dataset.topic)),flagged=$('#onlyFlagged').checked,counts=new Map(),total=[0,0,0,0,0];const add=(a,q)=>{const r=state.responses[q.id],answered=!!r?.value,checked=answered&&r.revealed&&(q.correct||[]).length,correct=checked&&isCorrect(r.value,q.correct);a[0]++;a[1]+=+answered;a[2]+=+!!correct;a[3]+=+!!(checked&&!correct);a[4]+=+!!state.flags[q.id]};for(const q of index){if(!difficulties.has(q.difficulty)||flagged&&!state.flags[q.id])continue;for(const key of ['s:'+q.subject,'d:'+q.subject+'|'+q.domain,'t:'+groupKey(q)]){if(!counts.has(key))counts.set(key,[0,0,0,0,0]);add(counts.get(key),q)}if(selected.has(groupKey(q)))add(total,q)}const format=a=>{const n=(a||[0,0,0,0,0]).map(v=>v.toLocaleString());return `${n[0]} questions · ${n[1]} answered · ${n[2]} correct · ${n[3]} incorrect · ${n[4]} marked for review`};for(const [attr,prefix] of [['topicStats','t:'],['subjectStats','s:'],['domainStats','d:']]){const selector=attr.replace(/[A-Z]/g,m=>'-'+m.toLowerCase());$$('[data-'+selector+']').forEach(el=>el.textContent=format(counts.get(prefix+el.dataset[attr])))}$('#clearSelectedProgress').disabled=!selected.size;$('#filterCount').textContent=format(total)}
