$('#response').oninput=()=>{if(!current)return;state.responses[current.id]={value:$('#response').value.trim(),revealed:false};persist();$('#answer').hidden=true;updateStats()};
function numeric(s){s=String(s).trim().replace(/,/g,'');if(/^[+-]?(\d+(\.\d*)?|\.\d+)$/.test(s))return Number(s);const m=s.match(/^([+-]?\d+(?:\.\d+)?)\s*\/\s*(\d+(?:\.\d+)?)$/);return m&&Number(m[2])!==0?Number(m[1])/Number(m[2]):NaN}
