$('#navigatorBtn').onclick=()=>{navLimit=200;$('#navSearch').value='';renderNav();openDialog('#navigatorDialog')};$('#navSearch').oninput=()=>{navLimit=200;renderNav()};function renderNav(){const grid=$('#navGrid');grid.replaceChildren();const filter=$('#navSearch').value.trim().toLowerCase();const list=session.map((q,i)=>({q,i})).filter(({q})=>q.id.toLowerCase().includes(filter));list.slice(0,navLimit).forEach(({q,i})=>{const b=document.createElement('button');b.textContent=(i+1)+(state.flags[q.id]?' ⚑':'');b.title=q.id;b.setAttribute('aria-label','Question '+(i+1)+', ID '+q.id+(state.flags[q.id]?', marked for review':'')+(state.responses[q.id]?.value?', answered':''));if(pos===i)b.setAttribute('aria-current','true');b.className=(state.responses[q.id]?.value?'answered ':'')+(pos===i?'current':'');b.onclick=()=>{pos=i;$('#navigatorDialog').close();showQuestion()};grid.append(b)});if(list.length>navLimit){const b=document.createElement('button');b.textContent='More…';b.onclick=()=>{navLimit+=200;renderNav()};grid.append(b)}}
