async function init(){try{const r=await fetch('index.json');if(!r.ok)throw Error();const data=await r.json();index=data.questions;$('#bankInfo').textContent=`${index.length.toLocaleString()} official SAT questions: ${index.filter(q=>q.subject==='Reading and Writing').length.toLocaleString()} Reading and Writing and ${index.filter(q=>q.subject==='Math').length.toLocaleString()} Math. Retrieved ${data.retrieved}. ${data.missing} missing content records.`;const map=new Map(index.map(q=>[q.id,q]));questionMap=new Map();for(const q of index){questionMap.set(q.id.toLowerCase(),q);if(q.externalId)questionMap.set(q.externalId.toLowerCase(),q)}session=(state.session||[]).map(id=>map.get(id)).filter(Boolean);if(!session.length||state.sessionVersion!==2&&session.length===1){const topics=state.topics?new Set(state.topics):null,difficulties=new Set(state.difficulties||['E','M','H']);session=index.filter(q=>(!topics||topics.has(groupKey(q)))&&difficulties.has(q.difficulty)&&(!state.onlyFlagged||state.flags[q.id]));if(!session.length)session=[...index]}state.sessionVersion=2;pos=Math.max(0,Math.min(state.pos||0,session.length-1));const linked=map.get(new URL(location.href).searchParams.get('q'));if(linked){let i=session.findIndex(q=>q.id===linked.id);if(i<0){session=[linked,...session];i=0}pos=i}await showQuestion()}catch{$('#loading').textContent='The question bank could not load. Reload the page to try again.'}}init();
